// Serves the brand logo images (192px / 512px) for manifest.json PWA icons.
// Binary files cannot be pushed through the available GitHub tooling, so the
// JPEGs are embedded here as base64 text and decoded at request time.
// NOTE: uses the direct (req,res) pattern — NOT webCompatible — because the
// bridge's replyNode() does res.end(await response.text()), which corrupts binary.
const LOGO_192_B64 = "";
const LOGO_512_B64 = "";

export default function handler(req, res) {
  const size = String((req.query && req.query.size) || '');
  const b64 = size === '192' ? LOGO_192_B64 : size === '512' ? LOGO_512_B64 : '';
  if (!b64) { res.status(404).send('not found'); return; }
  const buf = Buffer.from(b64, 'base64');
  res.setHeader('Content-Type', 'image/jpeg');
  res.setHeader('Content-Length', String(buf.length));
  res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
  res.status(200).end(buf);
}
